40	export const LIMITS = {
41	  maxLines: 100,
42	  maxQtyPerLine: 1000,
43	  maxSkuLength: 64,
44	  maxNameLength: 200,
45	  maxIdLength: 100,
46	  maxEmailLength: 254,
47	  /** Upper bound of an order total in minor units; protects against absurd inputs. */
48	  maxTotalMinor: 100_000_000,
49	} as const;
