51	const SKU_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;
52	const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
53	
54	/**
55	 * Builds a placed order after checking every invariant:
56	 * at least one line, positive integer quantities, prices as integer minor units,
57	 * a supported currency and a bounded total. All problems are reported together.
58	 */
59	export function createOrder(input: NewOrder, meta: { id: string; placedAt: string }): Order {
60	  const issues = collectIssues(input);
61	  if (issues.length > 0) {
62	    throw new ValidationError(issues);
63	  }
64	  return {
65	    id: meta.id,
66	    customerId: input.customerId,
67	    customerEmail: input.customerEmail,
68	    lines: input.lines.map((line) => ({
69	      sku: line.sku,
70	      name: line.name,
71	      qty: line.qty,
72	      unitPriceCents: line.unitPriceCents,
73	    })),
74	    status: "placed",
75	    channel: input.channel,
76	    currency: input.currency,
77	    placedAt: meta.placedAt,
78	  };
79	}
